const lavaHoundSheet=new Image();lavaHoundSheet.assetSrc='assets/lava-hound-v1.png';
function beginLavaHound(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'lavaHitConfirm',bespoke:true,windup:.75,origin:{x:e.x,y:e.y},angle,bit:false,confirmed:false,breathed:false};}
function lavaHoundContains(a,point,breath=false){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,delta=Math.atan2(dy,dx)-a.angle;delta=Math.atan2(Math.sin(delta),Math.cos(delta));return Math.hypot(dx,dy)<=(breath?220:105)+1e-8&&Math.abs(delta)<=(breath?Math.PI/6:Math.PI*11/36)+1e-8;}
const lavaHoundHitBase=hit;hit=(e,d)=>lavaHoundHitBase(e,d*(e.species==='r7e0'&&e.hp>0&&e.lavaHoundOpen>0&&!e.dotTick?1.4:1));
const lavaHoundAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r7e0')return lavaHoundAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);if(e.lavaHoundOpen>0){e.lavaHoundOpen=Math.max(0,Math.round((e.lavaHoundOpen-dt)*1e6)/1e6);e.attack=null;e.state='idle';e.t=1;return;}let a=e.attack;
 if(a?.pattern!=='lavaHitConfirm'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=125&&clear){beginLavaHound(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.6;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,112*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,21)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.bit&&e.elapsed>=.75){a.bit=true;e.struck=true;let hp=p.hp;if(lavaHoundContains(a,p)&&lineClear(a.origin,p))hurt(52);a.confirmed=p.hp<hp;playSound('impact',e.x,e.y);if(!a.confirmed){e.lavaHoundOpen=Math.max(0,2-Math.max(0,e.elapsed-.75));e.attack=null;e.state='idle';e.t=1;return;}a.windup=1.45;e.struck=false;}
 if(!dead&&a.confirmed&&!a.breathed&&e.elapsed>=1.45){a.breathed=true;e.struck=true;if(lavaHoundContains(a,p,true)&&lineClear(a.origin,p))hurt(72);playSound('fire',e.x,e.y);}if(e.elapsed>=2.3){e.attack=null;e.state='idle';e.t=2.2;}
};
const lavaHoundDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r7e0'||!lavaHoundSheet.complete||!lavaHoundSheet.naturalWidth||!lavaHoundSheet.naturalHeight)return lavaHoundDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0||e.lavaHoundOpen>0)f={row:2,col:3};else if(e.attack?.pattern==='lavaHitConfirm')f={row:2,col:e.elapsed<.75?0:e.elapsed<1.1?1:e.elapsed<1.7?2:3};let q=project(e.x,e.y),sw=lavaHoundSheet.naturalWidth/4,sh=lavaHoundSheet.naturalHeight/3,w=250,h=w*sh/sw,anchor=[.84,.82,.83][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,lavaHoundSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(lavaHoundSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const lavaHoundSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r7e0'?165:lavaHoundSizeBase(e);
const lavaHoundGroundBase=drawGroundEffects;drawGroundEffects=()=>{lavaHoundGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r7e0'):enemies)){if(e.species!=='r7e0'||e.hp<=0||!visibleAt(e.x,e.y))continue;if(e.lavaHoundOpen>0){groundRing(e.x,e.y,40,'#9bddcf',2);continue;}let a=e.attack;if(a?.pattern!=='lavaHitConfirm'||e.elapsed>=1.65)continue;let breath=a.confirmed,angle=breath?Math.PI/6:Math.PI*11/36,q=project(a.origin.x,a.origin.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle=breath?'#ef6e322b':'#e2af6622';ctx.strokeStyle=breath?'#ff9563':'#e2af66';ctx.lineWidth=breath&&a.breathed?3:1;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,breath?220:105,a.angle-angle,a.angle+angle);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}};
